        var alloc = repo1.findAllocationByKey("ak-p");
        repo1.updateAllocationStatus(alloc.id(), "APPROVED", 3L);
        repo1.insertCurtailment(windowId, new BigDecimal("8.000"), 4L);
        // second "run" — brand new JdbcTemplate on the same file
        JdbcTemplate jdbc2 = new JdbcTemplate(new SimpleDriverDataSource(new org.h2.Driver(), url, "sa", ""));
        WaterRepository repo2 = new WaterRepository(jdbc2);
        WindowRow w = repo2.findWindowById(windowId);
